-- =============================================================================
-- seed.sql
-- The setup the system uses, extracted from
-- legacy-db/YPLogicCurrentConsolidated.accdb with mdbtools.
--
-- Includes: rooms and their rates, the price list, tax and exchange rates,
-- and the pick lists the screens and rules read.
-- Excludes: guest, booking, charge and payment records (PII and old
-- payment-card fields), which supabase/tools/export_access_data.py loads,
-- and the Access tables nothing in the system reads.
-- =============================================================================

set search_path = ypl, public;

truncate table
  ypl.lookup_inventory_types,
  ypl.lookup_payment_categories,
  ypl.lookup_payment_types,
  ypl.lookup_phone_fax_types,
  ypl.lookup_room_rate_codes,
  ypl.lookup_room_rate_types,
  ypl.lookup_room_types,
  ypl.lookup_salutations,
  ypl.lookup_tax_rate_types,
  ypl.lookup_transaction_types,
  ypl.exchange_rates,
  ypl.tax_rates,
  ypl.rooms,
  ypl.room_rates,
  ypl.inventory_items
restart identity cascade;

